#!/usr/bin/env bash
# asb-mods shared environment — single source of truth for AI tooling env
# Generated by consolidation (task-3 audit). Source in ~/.zshenv or ~/.bashrc.
# This replaces per-tool env duplication across ~/.zshrc, ~/.zprofile, ~/.bash_profile

set -euo pipefail

# --- CA Bundle Resolution (fix Netskope/homebrew conflict) ---
# Priority: HOME > .netrc-ca > homebrew-ca > system-ca
if [ -f "$SSL_CERT_FILE" ]; then
    export REQUESTS_CA_BUNDLE="$SSL_CERT_FILE"
    export CURL_CA_BUNDLE="$SSL_CERT_FILE"
elif [ -f "$HOME/.config/ssl/ca-bundle.pem" ]; then
    export SSL_CERT_FILE="$HOME/.config/ssl/ca-bundle.pem"
    export REQUESTS_CA_BUNDLE="$SSL_CERT_FILE"
    export CURL_CA_BUNDLE="$SSL_CERT_FILE"
fi

# --- AI Tool API Keys (load from centralized secrets.env) ---
ASB_SHARED_ENV_DIR="${ASB_SHARED_ENV_DIR:-$HOME/.config/asb-mods/env}"
SECRETS_ENV="$ASB_SHARED_ENV_DIR/secrets.env"

if [ -f "$SECRETS_ENV" ]; then
    set -a
    source "$SECRETS_ENV"
    set +a
    unset SECRETS_ENV
fi

# --- Homebrew PATH ---
export PATH="/opt/homebrew/bin:$PATH"

# --- PNPM Global Bin (pnpm modules) ---
if [ -d "$HOME/Library/pnpm" ]; then
    export PATH="$HOME/Library/pnpm:$PATH"
fi

# --- Pi Coding Agent ---
# Model pin (must match all components): Qwen3.8-Flash-Next-oQ4e-mtp
export PI_DEFAULT_PROVIDER="omlx"
export PI_DEFAULT_MODEL="Qwen3.8-Flash-Next-oQ4e-mtp"
export LOCALLLM_OMLX_BASE_URL="http://127.0.0.1:1234/v1"

# --- Mnemosyne LLM Config ---
export MNEMOSYNE_LLM_BASE_URL="http://127.0.0.1:1234/v1"
export MNEMOSYNE_LLM_MODEL="Qwen3.8-Flash-Next-oQ4e-mtp"
export MNEMOSYNE_LLM_EXTRA_BODY='{"enable_thinking": true}'

# --- Cross-session memory ---
export ENGRAM_DATA_DIR="$HOME/.engram"
export MNEMOSYNE_MCP_BANK="default"

# --- GitNexus ---
export GITNEXUS_MAX_FILE_SIZE=""  # use CLI default (512 KB)

# --- RTK (Real-Time Keyboard) ---
export RTK_DB_PATH="$HOME/.local/share/rtk"

# --- Permission Modes ---
export PI_PERMISSION_MODE="yolo"  # or "sandboxed" / "standard"

# --- Paseo Terminal (if available) ---
# PASEO_TERMINAL_ID set by paseo server, not here

echo "[asb-mods] environment loaded"
